const el=id=>document.getElementById(id),previewState={open:false,boiling:false};
const apparatusPart=(type,x,y,size,volume=0,colour='#e7f3f2',layers=null,rotation=0)=>`<g transform="translate(${x} ${y}) rotate(${rotation} ${size/2} ${size/2})">${scientificGlassSvg(type,volume,100,colour,'preview',layers,null,{stopcockClosed:!previewState.open}).replace('width="68" height="68"',`x="0" y="0" width="${size}" height="${size}"`)}</g>`;
const structureDefs=`<defs><linearGradient id="preview-steel"><stop stop-color="#6a8299"/><stop offset=".25" stop-color="#c4d5e2"/><stop offset=".47" stop-color="#839aae"/><stop offset=".8" stop-color="#3e566f"/><stop offset="1" stop-color="#8da3b6"/></linearGradient></defs>`;
function drawFunnel(){const volume=Number(el('funnelVolume').value),choice=el('phaseChoice').value,top=choice==='iodine'?'#8657bd':'#edf4f2',bottom=choice==='dense'?'#edf4f2':choice==='iodine'?'#d8ce94':'#edf4f2',layers=[{volume:volume*.45,color:top},{volume:volume*.55,color:bottom}],label=choice==='dense'?['Water · upper phase','Dichloromethane · lower phase']:['Hexane · upper phase','Water · lower phase'];el('funnelVolumeOut').textContent=volume+' mL / 100 mL';el('funnelScene').innerHTML=`<svg viewBox="0 0 500 380" role="img" aria-label="${volume?'Pear-shaped separating funnel with two liquid phases and stopcock':'Empty separating funnel with stopcock'}">${structureDefs}<ellipse cx="215" cy="351" rx="111" ry="5" fill="#000" opacity=".15"/><rect x="106" y="345" width="216" height="10" rx="3" fill="url(#preview-steel)"/><rect x="125" y="38" width="8" height="308" rx="3" fill="url(#preview-steel)"/><path d="M130 146H216" stroke="url(#preview-steel)" stroke-width="7"/><rect x="120" y="135" width="19" height="24" rx="3" fill="url(#preview-steel)"/>${apparatusPart('separatoryFunnel',65,25,325,volume,top,layers)}<path d="M203 147Q225 153 249 147" fill="none" stroke="#849fb2" stroke-width="3"/><g opacity="${volume?1:0}" font-family="Segoe UI,Arial" font-size="10" fill="#b8cddc"><path d="M286 160H332M279 205H332" stroke="#90b5c7" stroke-width=".7"/><circle cx="286" cy="160" r="2" fill="#c5e1e9"/><circle cx="279" cy="205" r="2" fill="#c5e1e9"/><text x="340" y="164">${label[0]}</text><text x="340" y="209">${label[1]}</text></g></svg>`;}
function drawDistillation(){const volume=Number(el('distillVolume').value);el('distillVolumeOut').textContent=volume+' mL / 100 mL';el('distillScene').classList.toggle('boiling',previewState.boiling&&volume>0);el('distillScene').classList.toggle('distilling',previewState.boiling&&volume>0);el('distillScene').innerHTML=`<svg viewBox="0 0 500 380" role="img" aria-label="Simple distillation, with thermometer bulb at the sidearm and lower-end cooling-water inlet">${structureDefs}<ellipse cx="238" cy="352" rx="182" ry="5" fill="#000" opacity=".15"/><rect x="63" y="342" width="190" height="11" rx="3" fill="url(#preview-steel)"/><rect x="79" y="58" width="7" height="285" rx="2" fill="url(#preview-steel)"/><path d="M85 247H159" stroke="url(#preview-steel)" stroke-width="6"/><rect x="74" y="235" width="19" height="23" rx="3" fill="url(#preview-steel)"/>${apparatusPart('roundBottom',87.5,232,130,volume,'#8254b9')}${apparatusPart('distillationHead',106,138,120,0)}<path d="M152 87V181" stroke="#b5dfef" stroke-width="5" stroke-linecap="round"/><path d="M152 117V181" stroke="#db6c73" stroke-width="1.6"/><circle cx="152" cy="183" r="2.7" fill="#e6787b"/><g stroke="#a8ccdf" stroke-width=".6">${[95,103,111,119,127,135,143,151].map(y=>`<path d="M154 ${y}h3"/>`).join('')}</g><g transform="translate(196 167) rotate(16)">${apparatusPart('liebigCondenser',-17,-70,174,0)}</g><path d="M330 223L353 255L355 272" fill="none" stroke="#97becf" stroke-width="6"/><path d="M330 223L353 255L355 272" fill="none" stroke="#dff4ff" stroke-width="3"/><path d="M352 255L360 278" stroke="#719daf" stroke-width="4"/><path d="M353 255L360 278" stroke="#dff4ff" stroke-width="1.4"/><path d="M300 254Q365 270 412 249M221 155Q243 128 275 131" fill="none" stroke="#73b0ba" stroke-opacity=".65" stroke-width="3"/><path d="M347 264H361V286L377 327Q382 339 370 339H337Q324 339 330 327L347 286Z" fill="#c0e7f1" fill-opacity=".1" stroke="#a4c9da" stroke-width="1.2"/><path d="M334 323H373L378 331Q380 336 370 336H338Q329 336 331 331Z" fill="#d2eff0" fill-opacity=".4"/><ellipse cx="354" cy="323" rx="20" ry="1.8" fill="#d2eff0" fill-opacity=".2" stroke="#d9f4f8" stroke-width=".5"/><path d="M95 336H211L202 368H104Z" fill="#40526b" stroke="#8299ad" stroke-width="1"/><ellipse cx="153" cy="336" rx="58" ry="10" fill="#6b7a8f"/><ellipse cx="153" cy="336" rx="47" ry="6" fill="#2a384d"/><circle cx="189" cy="354" r="4" fill="#a1b2c0"/><circle cx="111" cy="355" r="2" fill="${previewState.boiling?'#dba37a':'#718391'}"/><g font-family="Segoe UI,Arial" font-size="9" fill="#acc6d6"><text x="166" y="94">Thermometer</text><text x="277" y="118">Water out · upper end</text><text x="374" y="245">Water in</text><text x="332" y="363">Receiver · open to air</text><text x="103" y="378">Heating mantle</text></g></svg>`;}
for(const id of ['funnelVolume','phaseChoice'])el(id).addEventListener('input',drawFunnel);el('distillVolume').addEventListener('input',drawDistillation);
el('stopcock').onclick=()=>{previewState.open=!previewState.open;el('stopcock').setAttribute('aria-pressed',String(previewState.open));el('stopcock').textContent=previewState.open?'Inspect closed stopcock':'Inspect open stopcock';drawFunnel();};
el('boiling').onclick=()=>{previewState.boiling=!previewState.boiling;el('boiling').setAttribute('aria-pressed',String(previewState.boiling));el('boiling').textContent=previewState.boiling?'Pause boiling illustration':'Show boiling & condensation';drawDistillation();};
for(const kind of ['funnel','distill']){let position={x:0,y:0},drag=null,scene=el(kind+'Scene');const transform=()=>scene.style.transform=`translate(${position.x}px,${position.y}px) rotate(${el(kind+'Rotation').value}deg) scale(${el(kind+'Zoom').value/100})`;for(const suffix of ['Rotation','Zoom'])el(kind+suffix).addEventListener('input',transform);scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX-position.x,y:e.clientY-position.y};scene.setPointerCapture(e.pointerId);});scene.addEventListener('pointermove',e=>{if(!drag)return;position.x=Math.max(-70,Math.min(70,e.clientX-drag.x));position.y=Math.max(-40,Math.min(40,e.clientY-drag.y));transform();});scene.addEventListener('pointerup',()=>drag=null);scene.addEventListener('pointercancel',()=>drag=null);}
drawFunnel();drawDistillation();

const collectionNames={testtube:"Test tube",boilingTube:"Boiling tube",beaker:"Beaker",erlenmeyer:"Conical flask",flatBottom:"Flat-bottom flask",volumetricFlask:"Volumetric flask",cylinder:"Measuring cylinder",burette:"Burette",volumetricPipette:"Volumetric pipette",graduatedPipette:"Graduated pipette",dropper:"Dropper",gasjar:"Gas jar",watchGlass:"Watch glass",evaporatingDish:"Evaporating dish",crucible:"Crucible",soxhletExtractor:"Soxhlet extractor",thimble:"Extraction thimble",glassFunnel:"Glass funnel",filterPaper:"Filter paper",retortStand:"Retort stand",clamp:"Bosshead and clamp",testTubeClamp:"Test-tube clamp",bunsen:"Bunsen burner",spiritLamp:"Spirit lamp",hotPlate:"Hot plate",heatingMantle:"Heating mantle",waterBath:"Water bath",oilBath:"Oil bath",sandBath:"Sand bath",heatingBlock:"Heating block",tripod:"Tripod",wireGauze:"Wire gauze",glassRod:"Glass rod",washBottle:"Wash bottle",spatula:"Spatula",mortarPestle:"Mortar and pestle",balance:"Balance",splint:"Wooden splint",litmusPaper:"Litmus paper",universalPaper:"Universal indicator paper"};if(el("apparatusCollection"))el("apparatusCollection").innerHTML=Object.entries(collectionNames).map(([type,name])=>`<figure>${scientificGlassSvg(type,40,100,["litmusPaper","universalPaper"].includes(type)?"#a977b9":"#edf4f2","gallery")}<figcaption>${name}</figcaption></figure>`).join("");
